"""Package an existing rendered v3; never renders, generates audio, or transmits files."""
import hashlib,json,pathlib,shutil,subprocess
ED=pathlib.Path(__file__).resolve().parent;EP=ED.parent;REPO=ED.parents[3]
RENDER=ED/'render_v3';OUT=EP/'outputs/video-review-v3'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def digest(p):
    h=hashlib.sha256()
    with p.open('rb')as f:
        for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
    return h.hexdigest()
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
def srt_time(s):
    ms=round(s*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
manifest_path=RENDER/'full_render_manifest.json'
if not manifest_path.exists():raise RuntimeError('v3 completion manifest not present; packaging must wait')
render_manifest=read(manifest_path);video=RENDER/'namyangju-wangsuk_v3.mp4'
assert video.is_file()and video.stat().st_size>1000000
assert render_manifest.get('rendered')is True
entry=REPO/'video/src/NamyangjuV3.tsx';assert digest(entry)==render_manifest['source_sha256'],'render/source revision mismatch'
project=read(REPO/'video/src/namyangju-v2/project.json')
assert digest(REPO/'video/src/namyangju-v2/project.json')==render_manifest['data_sha256'],'render/project revision mismatch'
PROBE=REPO/'video/node_modules/@remotion/compositor-win32-x64-msvc/ffprobe.exe'
technical=json.loads(subprocess.check_output([str(PROBE),'-v','error','-show_streams','-show_format','-of','json',str(video)]))
OUT.mkdir(parents=True,exist_ok=True);master=OUT/'namyangju-wangsuk_v3.mp4'
if not master.exists():shutil.copy2(video,master)
assert digest(master)==digest(video),'master copy mismatch'
cues=[]
for c in project['chapters']:
    for cue in project['captions'][c['scene_id']]:
        start=c['start_s']+cue['start_s'];end=min(c['end_s'],c['start_s']+cue['end_s'])
        if end<=start:continue
        cues.append({'start_s':start,'end_s':end,'text':cue['text'],'basis':'scene measured duration / character-weight estimate; NOT forced aligned'})
srt='\n\n'.join(f"{i+1}\n{srt_time(c['start_s'])} --> {srt_time(c['end_s'])}\n{c['text']}"for i,c in enumerate(cues))+'\n'
(OUT/'namyangju-wangsuk_v3_estimated.srt').write_text(srt,encoding='utf-8-sig');save(OUT/'caption_basis.json',cues)
source_refs=read(ED/'render_v2/source_refs_v2.json');source_refs['revision']='v3-used-materials';source_refs['entry']='video/src/NamyangjuV3.tsx';source_refs['graphic_layouts']=['calendar','network','document','metrics','vertical_stage','bars','five_question_icons']
save(OUT/'sources_v3.json',source_refs);shutil.copy2(EP/'writer/script_v2.md',OUT/'narration_script_approved_v2.md')
audio=[]
for c in project['chapters']:
    original=EP/'narration/audio-v1'/f"{c['scene_id']}.mp3";public=REPO/'video/public'/c['audio']
    audio.append({'scene_id':c['scene_id'],'sha256':digest(original),'public_copy_matches':digest(original)==digest(public),'from_frame':c['from'],'frames':c['frames']})
report={'revision':'review-v3','status':'local_master_prepared_pending_independent_encoded_qa','video':'namyangju-wangsuk_v3.mp4','video_sha256':digest(master),'bytes':master.stat().st_size,'source_entry':'video/src/NamyangjuV3.tsx','source_sha256':digest(entry),'project_sha256':render_manifest['data_sha256'],'technical':technical,'frames':project['durationInFrames'],'shot_count':len(project['shots']),'approved_script':'script-v2','audio_revision':'audio-v1','audio_integrity':audio,'caption_basis':'character-weight estimate within measured scene audio; not actual word alignment','continuous_playback':False,'audio_listened':False,'paid_generation_or_telegram_file_upload':False,'qa_path':'qa/findings_video_v3.json if generated by independent QA'}
save(OUT/'manifest_v3.json',report);save(RENDER/'technical_v3.json',technical)
(OUT/'README.md').write_text('# 남양주 · 왕숙 검토본 v3\n\n`namyangju-wangsuk_v3.mp4`는 62개 의미별 샷으로 구성한 전체 본편입니다. 실제 지도·자료사진·AI 개념 이미지·달력·관계도·공고 문서·계획 규모 및 가격 차트를 사용했습니다. v1·v2와 승인 음성은 보존했습니다.\n\n해상도·코덱·실제 길이·SHA256은 `manifest_v3.json`, 사용 자료와 장면별 근거는 `sources_v3.json`에서 확인할 수 있습니다. 승인 대본은 `narration_script_approved_v2.md`입니다.\n\n`namyangju-wangsuk_v3_estimated.srt`는 장면 실제 음성 길이에 글자 비중을 적용한 추정 자막입니다. 실제 청취와 단어 정렬 검증을 완료한 자막이 아닙니다. 최종 오디오 자연스러움·문장 싱크는 별도 청취 검수 대상입니다.\n\n독립 QA의 실제 인코딩 영상 검수 결과는 episode의 `qa/findings_video_v3.json`을 기준으로 확인합니다. 이 패키지 생성만으로 전체 재생·청취 완료 또는 업로드 승인을 뜻하지 않습니다. 플랫폼 업로드와 텔레그램 영상 전송을 하지 않았습니다.\n',encoding='utf-8')
save(ED/'finalhandoff_v3.json',{'role':'editor','status':report['status'],'episode_root':str(EP),'output_root':str(OUT),'master':str(master),'manifest':str(OUT/'manifest_v3.json'),'srt':str(OUT/'namyangju-wangsuk_v3_estimated.srt'),'video_sha256':report['video_sha256'],'bytes':report['bytes'],'input_versions':{'script':'script-v2','audio':'audio-v1','binding':'shot-asset-binding-v2','visual':'visual-v5'},'verification':{'video_copy_sha_match':True,'audio_copies_all_match':all(a['public_copy_matches']for a in audio),'actual_listening':False,'continuous_playback':False},'next_role':'director and independent QA'})
print(json.dumps({'packaged':str(OUT),'bytes':report['bytes'],'sha256':report['video_sha256'],'captions':len(cues)}))
